function createStandingsHeaders(e){for(const t of e){console.log(t);const e=document.createElement("th");e.textContent=t;document.getElementById("standings-header-row").appendChild(e)}}document.addEventListener("DOMContentLoaded",(async()=>{const e=await fetch("/api/standings-headers/");if(!e.ok)throw new Error("Network response was not ok");const t=await e.json();createStandingsHeaders(t);const n=await fetch("/api/standings-data/");if(!n.ok)throw new Error("Network response was not ok");const o=await n.json(),a=document.getElementById("standings-container");let d=1;for(const e of o){const n=document.createElement("tr"),o=document.createElement("th");o.scope="row",o.textContent=d,d+=1,n.appendChild(o);for(const o of t){const t=document.createElement("td");t.textContent=e[o],n.appendChild(t)}a.appendChild(n)}document.getElementById("loading-div").remove()}));